import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { cwd } from 'node:process';
import { SANITY_FUNCTION_DOCUMENT, SANITY_FUNCTION_DURABLE, SANITY_FUNCTION_MEDIA_LIBRARY_ASSET, SANITY_FUNCTION_PUBSUB, SANITY_FUNCTION_SCHEDULED, SANITY_FUNCTION_SYNC_TAG_INVALIDATE, } from '../../../constants.js';
import { parseJsonObject } from '../../parse-json-object.js';
import buildPayload from '../build-payload.js';
import { fetchAsset, fetchDocument } from '../fetch-document.js';
export const defaultInvocationDeps = { fetchDocument, fetchAsset, buildPayload };
const assertNever = (resource) => {
    throw new Error(`No invocation plan for function type: ${resource.type}`);
};
const resolveDurableInvocationPlan = (event) => {
    switch (event?.type) {
        case 'document':
            return { kind: 'groq', inputSource: 'document', isDurable: true };
        case 'media-library':
            return { kind: 'groq', inputSource: 'media', isDurable: true };
        case 'sync-tag-invalidate':
        case undefined:
            return { kind: 'durable', inputSource: 'payload', isDurable: true };
    }
};
export const resolveInvocationPlan = (resource) => {
    switch (resource.type) {
        case SANITY_FUNCTION_DOCUMENT:
            return { kind: 'groq', inputSource: 'document', isDurable: false };
        case SANITY_FUNCTION_MEDIA_LIBRARY_ASSET:
            return { kind: 'groq', inputSource: 'media', isDurable: false };
        case SANITY_FUNCTION_DURABLE:
            return resolveDurableInvocationPlan(resource.event);
        case SANITY_FUNCTION_SCHEDULED:
        case SANITY_FUNCTION_PUBSUB:
        case SANITY_FUNCTION_SYNC_TAG_INVALIDATE:
            return { kind: 'plain', isDurable: false };
        default:
            return assertNever(resource);
    }
};
/**
 * True when the function's event is delivered through a GROQ rule (a document or
 * media-library event, whether plain or durable), so its payload is a document the
 * rule may narrow before the handler sees it.
 */
export const isGroqInvocation = (resource) => resolveInvocationPlan(resource).kind === 'groq';
export const collectInvokeInput = async (plan, input, deps) => {
    const source = plan.kind === 'groq' ? plan.inputSource : 'none';
    return resolveInvokeInput(source, input, deps);
};
export const buildContext = (plan, input) => {
    const withToken = input.withUserToken ? { token: input.token } : {};
    if (plan.kind === 'plain') {
        return {
            clientOptions: { ...withToken },
            resources: input.resources,
            blueprintFileDir: input.blueprintFileDir,
        };
    }
    const isMedia = plan.kind === 'groq' && plan.inputSource === 'media';
    return {
        clientOptions: {
            apiVersion: input.api,
            dataset: input.flags.dataset,
            projectId: input.projectId,
            organizationId: input.organizationId,
            ...withToken,
        },
        eventResourceType: isMedia ? 'media-library' : 'dataset',
        eventResourceId: (isMedia ? input.flags['media-library-id'] : `${input.projectId}.${input.flags.dataset}`) ||
            '',
        functionResourceType: 'project',
        functionResourceId: input.projectId || '',
        resources: input.resources,
        blueprintFileDir: input.blueprintFileDir,
    };
};
export const buildInvokeOptions = (plan, invokeInput, eventType) => {
    switch (plan.kind) {
        case 'groq':
            return {
                event: eventType,
                payload: invokeInput.payload,
                before: invokeInput.before,
                after: invokeInput.after,
            };
        case 'plain':
            // Cron functions have no payload, but pubsub and sync-tag-invalidate carry
            // whatever the producer sent, so pass it through for all of them.
            return { event: 'plain', payload: invokeInput.payload };
        case 'durable':
            return { event: 'durable', payload: invokeInput.payload };
    }
};
const resolveInvokeInput = async (source, input, deps) => {
    const { flags } = input;
    const fetchById = (id) => source === 'document'
        ? deps.fetchDocument(id, {
            projectId: input.projectId,
            dataset: flags.dataset,
            apiVersion: input.api,
            apiHost: input.apiHost,
            token: input.token,
        }, input.log)
        : deps.fetchAsset(id, {
            mediaLibraryId: flags['media-library-id'],
            apiVersion: input.api,
            apiHost: input.apiHost,
            token: input.token,
        }, input.log);
    let before = null;
    let after = null;
    if (flags['data-before'] && flags['data-after']) {
        before = parseJsonObject(flags['data-before']);
        after = parseJsonObject(flags['data-after']);
    }
    else if (flags['file-before'] && flags['file-after']) {
        before = parseJsonObject(readFileSync(join(cwd(), flags['file-before']), 'utf8'));
        after = parseJsonObject(readFileSync(join(cwd(), flags['file-after']), 'utf8'));
    }
    else if (flags['document-id-before'] && flags['document-id-after']) {
        before = await fetchById(flags['document-id-before']);
        after = await fetchById(flags['document-id-after']);
    }
    let payload;
    if (after)
        payload = after;
    else if (flags['document-id'])
        payload = await fetchById(flags['document-id']);
    else
        payload = deps.buildPayload({ data: flags.data, file: flags.file });
    return { payload, before, after };
};
